if id __USER__ >/dev/null 2>&1; then s="$(who 2>/dev/null | awk -v u=__USER__ '$1==u {print}')"; p="$(ps -u __USER__ -o pid=,etime=,comm=,args= 2>/dev/null | awk '$3=="(sd-pam)"{next} $3=="systemd" && / --user/{next} {print}')"; if [ -n "$s" ] || [ -n "$p" ]; then echo CNU_ACTIVE; [ -n "$s" ] && echo "login sessions: $s"; [ -n "$p" ] && printf 'running processes (pid, age, name, command):\n%s\n' "$p"; else echo CNU_IDLE; fi; else echo CNU_ABSENT; fi